import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
from io import BytesIO
import base64
import jinja2
import datetime
import os

plt.style.use('seaborn-v0_8-darkgrid')
COLORS = {
    'primary': '#006fcf', # Amex blueish
    'secondary': '#001f5b',
    'accent': '#00a3e0',
    'danger': '#e03a3e',
    'success': '#1a8b44',
    'gray': '#6c757d'
}

def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    buf.seek(0)
    img_str = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return f"data:image/png;base64,{img_str}"

def format_currency(val):
    return f"${val:,.2f}"

def format_percent(val):
    return f"{val:,.2f}%"

def load_data():
    df = pd.read_csv('/app/benchmark/data.csv')
    df['Date'] = pd.to_datetime(df['Date'], utc=True)
    df.sort_values('Date', inplace=True)
    df.set_index('Date', inplace=True)
    return df

def generate_report():
    df = load_data()

    # KPIs
    start_date = df.index.min()
    end_date = df.index.max()
    years = (end_date - start_date).days / 365.25

    start_price = df['Close'].iloc[0]
    end_price = df['Close'].iloc[-1]

    cumulative_return = ((end_price - start_price) / start_price) * 100
    cagr = ((end_price / start_price) ** (1 / years) - 1) * 100

    df['Daily_Return'] = df['Close'].pct_change()
    ann_volatility = df['Daily_Return'].std() * np.sqrt(252) * 100

    df['Running_Max'] = df['Close'].cummax()
    df['Drawdown'] = (df['Close'] - df['Running_Max']) / df['Running_Max']
    max_drawdown = df['Drawdown'].min() * 100

    total_dividends = df['Dividends'].sum()

    # Plot 1: Long-Term Price Trend (Log Scale)
    fig1, ax1 = plt.subplots(figsize=(10, 5))
    ax1.plot(df.index, df['Close'], color=COLORS['primary'], linewidth=1)
    ax1.set_yscale('log')
    ax1.set_title('AXP Close Price (Log Scale) 1972-2026', fontsize=14, fontweight='bold', color=COLORS['secondary'])
    ax1.set_ylabel('Price (USD)', fontsize=12)
    ax1.grid(True, which="both", ls="-", alpha=0.2)
    img_price_trend = fig_to_base64(fig1)

    # Plot 2: Drawdown (Underwater Chart)
    fig2, ax2 = plt.subplots(figsize=(10, 4))
    ax2.fill_between(df.index, df['Drawdown'] * 100, 0, color=COLORS['danger'], alpha=0.6)
    ax2.set_title('Drawdowns (Underwater Chart)', fontsize=14, fontweight='bold', color=COLORS['secondary'])
    ax2.set_ylabel('Drawdown (%)', fontsize=12)
    ax2.set_ylim([max_drawdown - 5, 0])
    ax2.grid(True, alpha=0.3)
    img_drawdown = fig_to_base64(fig2)

    # Plot 3: Volume Analysis
    fig3, ax3 = plt.subplots(figsize=(10, 4))
    # Resample to monthly mean for a cleaner volume chart
    monthly_volume = df['Volume'].resample('M').mean()
    ax3.bar(monthly_volume.index, monthly_volume, color=COLORS['accent'], width=20, alpha=0.7)
    ax3.set_title('Monthly Average Trading Volume', fontsize=14, fontweight='bold', color=COLORS['secondary'])
    ax3.set_ylabel('Volume', fontsize=12)
    ax3.grid(True, alpha=0.3)
    img_volume = fig_to_base64(fig3)

    # Plot 4: Dividends over time
    div_df = df[df['Dividends'] > 0]
    fig4, ax4 = plt.subplots(figsize=(10, 4))
    annual_div = df['Dividends'].resample('Y').sum()
    ax4.bar(annual_div.index, annual_div, color=COLORS['success'], width=250, alpha=0.8)
    ax4.set_title('Annual Dividend Payments Per Share', fontsize=14, fontweight='bold', color=COLORS['secondary'])
    ax4.set_ylabel('Total Dividends (USD)', fontsize=12)
    ax4.grid(True, alpha=0.3)
    img_dividends = fig_to_base64(fig4)

    # Decade-by-Decade Analysis
    df['Decade'] = (df.index.year // 10) * 10
    decades = df['Decade'].unique()
    decade_stats = []

    for dec in sorted(decades):
        dec_data = df[df['Decade'] == dec]
        if len(dec_data) == 0: continue
        d_start = dec_data['Close'].iloc[0]
        d_end = dec_data['Close'].iloc[-1]
        d_ret = ((d_end - d_start) / d_start) * 100
        d_vol = dec_data['Daily_Return'].std() * np.sqrt(252) * 100
        d_div = dec_data['Dividends'].sum()
        decade_stats.append({
            'Decade': f"{dec}s",
            'Return': f"{d_ret:.2f}%",
            'Volatility': f"{d_vol:.2f}%",
            'Dividends': f"${d_div:.2f}"
        })

    html_template = """
    <!DOCTYPE html>
    <html lang="en">
    <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>American Express (AXP) Historical Stock Performance Report</title>
        <style>
            :root {
                --primary: #006fcf;
                --secondary: #001f5b;
                --accent: #00a3e0;
                --text-main: #333333;
                --bg-light: #f4f7f6;
                --border: #e0e0e0;
                --danger: #e03a3e;
            }
            body {
                font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
                line-height: 1.6;
                color: var(--text-main);
                background-color: var(--bg-light);
                margin: 0;
                padding: 0;
            }
            .container {
                max-width: 1000px;
                margin: 40px auto;
                background: #ffffff;
                padding: 40px 50px;
                border-radius: 8px;
                box-shadow: 0 4px 15px rgba(0,0,0,0.05);
            }
            h1, h2, h3 { color: var(--secondary); margin-bottom: 20px; }
            h1 { font-size: 2.2rem; border-bottom: 2px solid var(--primary); padding-bottom: 10px; }
            h2 { font-size: 1.6rem; margin-top: 40px; border-bottom: 1px solid var(--border); padding-bottom: 5px; }
            .brief {
                font-size: 1.1rem;
                color: #555;
                font-style: italic;
                margin-bottom: 30px;
            }
            /* Dashboard KPIs */
            .kpi-dashboard {
                display: flex;
                flex-wrap: wrap;
                gap: 20px;
                margin: 30px 0;
            }
            .kpi-card {
                flex: 1 1 calc(33.333% - 20px);
                background: #fdfdfd;
                border: 1px solid var(--border);
                border-left: 5px solid var(--primary);
                padding: 20px;
                border-radius: 6px;
                box-shadow: 0 2px 5px rgba(0,0,0,0.02);
            }
            .kpi-card.danger { border-left-color: var(--danger); }
            .kpi-title { font-size: 0.9rem; text-transform: uppercase; color: #777; font-weight: bold; margin-bottom: 5px; }
            .kpi-value { font-size: 1.8rem; font-weight: bold; color: var(--secondary); margin-bottom: 5px; }
            .kpi-desc { font-size: 0.85rem; color: #666; }

            .chart-container {
                margin: 30px 0;
                text-align: center;
                border: 1px solid var(--border);
                padding: 15px;
                border-radius: 6px;
                background: #fafafa;
            }
            .chart-container img {
                max-width: 100%;
                height: auto;
            }
            table {
                width: 100%;
                border-collapse: collapse;
                margin: 20px 0;
            }
            th, td {
                padding: 12px 15px;
                text-align: left;
                border-bottom: 1px solid var(--border);
            }
            th { background-color: var(--secondary); color: white; text-transform: uppercase; font-size: 0.9rem; }
            tr:hover { background-color: #f1f1f1; }
            .footer {
                margin-top: 50px;
                padding-top: 20px;
                border-top: 1px solid var(--border);
                text-align: center;
                font-size: 0.9rem;
                color: #888;
            }
        </style>
    </head>
    <body>
        <div class="container">
            <h1>American Express (AXP) Historical Stock Performance Report</h1>
            <p class="brief">A comprehensive analysis of American Express stock performance spanning over 50 years (1972&ndash;2026), covering price trends, volatility, dividend history, and key market events.</p>

            <section id="executive-overview">
                <h2>Executive Overview</h2>
                <p>Since its earliest adjusted trading records in 1972, American Express (AXP) has demonstrated remarkable long-term capital appreciation, navigating multiple economic cycles, market crashes, and technological shifts. The stock has grown from an adjusted starting price of <strong>{{ start_price }}</strong> to <strong>{{ end_price }}</strong>.</p>

                <div class="kpi-dashboard">
                    <div class="kpi-card">
                        <div class="kpi-title">Cumulative Total Return</div>
                        <div class="kpi-value">{{ cumulative_return }}</div>
                        <div class="kpi-desc">Total percentage return (capital appreciation).</div>
                    </div>
                    <div class="kpi-card">
                        <div class="kpi-title">CAGR</div>
                        <div class="kpi-value">{{ cagr }}</div>
                        <div class="kpi-desc">Compounded Annual Growth Rate.</div>
                    </div>
                    <div class="kpi-card danger">
                        <div class="kpi-title">Maximum Drawdown</div>
                        <div class="kpi-value">{{ max_drawdown }}</div>
                        <div class="kpi-desc">Worst-case peak-to-trough decline.</div>
                    </div>
                    <div class="kpi-card">
                        <div class="kpi-title">Annualized Volatility</div>
                        <div class="kpi-value">{{ ann_volatility }}</div>
                        <div class="kpi-desc">Standard deviation of daily returns (annualized).</div>
                    </div>
                    <div class="kpi-card">
                        <div class="kpi-title">Total Dividends</div>
                        <div class="kpi-value">{{ total_dividends }}</div>
                        <div class="kpi-desc">Cumulative dividends paid per share.</div>
                    </div>
                </div>
            </section>

            <section id="price-trend-analysis">
                <h2>Long-Term Price Trend Analysis</h2>
                <p>The long-term trajectory of AXP reveals steady secular growth punctuated by significant bear markets. Displayed below is the stock's closing price on a logarithmic scale, allowing for visual comparison of percentage growth over time.</p>
                <div class="chart-container">
                    <img src="{{ img_price_trend }}" alt="Long-Term Price Trend">
                </div>
            </section>

            <section id="volatility-risk">
                <h2>Volatility & Risk Assessment</h2>
                <p>Risk management is paramount for a long-term holding. The underwater chart below visualizes every drawdown from previous all-time highs. Major historical events such as the 1987 Black Monday crash, the 2008 Global Financial Crisis (which posed a severe systemic threat to financial institutions), and the 2020 COVID-19 pandemic are clearly identifiable as deep troughs.</p>
                <div class="chart-container">
                    <img src="{{ img_drawdown }}" alt="Drawdown Chart">
                </div>
            </section>

            <section id="volume-analysis">
                <h2>Trading Volume Analysis</h2>
                <p>Trading volume serves as an indicator of market interest and liquidity. Over the decades, AXP's liquidity has structurally expanded, reflecting the broader democratization and institutionalization of equity markets.</p>
                <div class="chart-container">
                    <img src="{{ img_volume }}" alt="Volume Trend">
                </div>
            </section>

            <section id="dividends-splits">
                <h2>Dividend History & Stock Splits</h2>
                <p>For long-term shareholders, dividends represent a crucial component of total return. American Express has maintained a consistent dividend policy, with absolute payouts growing over the analysis period. The chart below tracks annual cumulative dividend payments per share.</p>
                <div class="chart-container">
                    <img src="{{ img_dividends }}" alt="Annual Dividends">
                </div>
            </section>

            <section id="decade-comparison">
                <h2>Decade-by-Decade Performance Comparison</h2>
                <p>Analyzing AXP's performance across distinct decades provides insight into how the company performed during varying economic regimes—from the stagflation of the 1970s through the high-growth 1990s and the turbulent 2000s.</p>
                <table>
                    <thead>
                        <tr>
                            <th>Decade</th>
                            <th>Capital Return</th>
                            <th>Annualized Volatility</th>
                            <th>Total Dividends Paid</th>
                        </tr>
                    </thead>
                    <tbody>
                        {% for row in decade_stats %}
                        <tr>
                            <td><strong>{{ row.Decade }}</strong></td>
                            <td>{{ row.Return }}</td>
                            <td>{{ row.Volatility }}</td>
                            <td>{{ row.Dividends }}</td>
                        </tr>
                        {% endhof %}
                    </tbody>
                </table>
            </section>

            <div class="footer">
                <p>Generated automatically by the Financial Reporting Engine | Data Source: AXP Daily Stock Prices (1972-2026)</p>
            </div>
        </div>
    </body>
    </html>
    """

    # Render with Jinja2
    template = jinja2.Template(html_template)
    html_content = template.render(
        start_price=format_currency(start_price),
        end_price=format_currency(end_price),
        cumulative_return=format_percent(cumulative_return),
        cagr=format_percent(cagr),
        max_drawdown=format_percent(max_drawdown),
        ann_volatility=format_percent(ann_volatility),
        total_dividends=format_currency(total_dividends),
        img_price_trend=img_price_trend,
        img_drawdown=img_drawdown,
        img_volume=img_volume,
        img_dividends=img_dividends,
        decade_stats=decade_stats
    )

    # The template has a typo: `{% endhof %}` -> `{% endfor %}`. Let's fix that.
    html_content = html_content.replace('{% endhof %}', '') # It will actually crash if rendered with typo. I should fix it before passing to jinja2. Wait, let me rewrite the script.

if __name__ == '__main__':
    generate_report()
